import pytest
from topological_ordering import topological_ordering


class Node:
    """测试用图节点，具有 incoming_nodes 和 outgoing_nodes 属性。"""

    def __init__(self, name, incoming_nodes=None, outgoing_nodes=None):
        self.name = name
        self.incoming_nodes = set(incoming_nodes) if incoming_nodes else set()
        self.outgoing_nodes = set(outgoing_nodes) if outgoing_nodes else set()

    def __repr__(self):
        return f"Node({self.name})"

    def __hash__(self):
        return hash(self.name)

    def __eq__(self, other):
        return isinstance(other, Node) and self.name == other.name


def _build_chain():
    """构造链式图 A->B->C。"""
    a = Node("A")
    b = Node("B")
    c = Node("C")
    a.outgoing_nodes = {b}
    b.incoming_nodes = {a}
    b.outgoing_nodes = {c}
    c.incoming_nodes = {b}
    return a, b, c


def _build_diamond():
    """构造菱形图 A->B, A->C, B->D, C->D。"""
    a = Node("A")
    b = Node("B")
    c = Node("C")
    d = Node("D")
    a.outgoing_nodes = {b, c}
    b.incoming_nodes = {a}
    b.outgoing_nodes = {d}
    c.incoming_nodes = {a}
    c.outgoing_nodes = {d}
    d.incoming_nodes = {b, c}
    return a, b, c, d


def _assert_topological_order(result, nodes):
    """校验结果包含所有节点且满足拓扑序（每条边 u->v 中 u 在 v 之前）。"""
    assert len(result) == len(nodes)
    assert set(result) == set(nodes)
    position = {node: idx for idx, node in enumerate(result)}
    for node in nodes:
        for nextnode in node.outgoing_nodes:
            if nextnode in position:
                assert position[node] < position[nextnode]


